import Gio from 'gi://Gio';
import GLib from 'gi://GLib';
import Meta from 'gi://Meta';
import St from 'gi://St';
import { Extension } from 'resource:///org/gnome/shell/extensions/extension.js';

const PRIVACY_TYPES = new Set([
    'x-kde-passwordmanagerhint',
    'org.nspasteboard.concealedtype',
    'org.nspasteboard.autogeneratedtype',
    'x-clipd-ignore',
]);

export default class ClipboardLxExtension extends Extension {
    enable() {
        this._clipCtl = GLib.build_filenamev([GLib.get_home_dir(), '.local', 'bin', 'clip-ctl']);
        this._selection = global.display.get_selection();
        this._ownerChangedId = this._selection.connect('owner-changed', (_sel, selectionType, _source) => {
            if (selectionType !== Meta.SelectionType.SELECTION_CLIPBOARD)
                return;

            let mimetypes = [];
            try {
                mimetypes = this._selection.get_mimetypes(Meta.SelectionType.SELECTION_CLIPBOARD) || [];
            } catch (_e) {
                mimetypes = [];
            }

            const lowerTypes = mimetypes.map(t => t.toLowerCase());
            if (lowerTypes.some(t => PRIVACY_TYPES.has(t)))
                return;

            const hasPng = lowerTypes.includes('image/png');
            const hasPlainText = lowerTypes.some(t =>
                t === 'utf8_string' ||
                t === 'text/plain;charset=utf-8' ||
                t === 'text/plain' ||
                t === 'string' ||
                t === 'text'
            );

            if (hasPng && !hasPlainText) {
                this._notifyChange();
                return;
            }

            try {
                St.Clipboard.get_default().get_text(St.ClipboardType.CLIPBOARD, (_cb, text) => {
                    if (text && text.trim().length > 0) {
                        this._sendText(text);
                    } else {
                        this._notifyChange();
                    }
                });
            } catch (_e) {
                this._notifyChange();
            }
        });
    }

    _sendText(text) {
        try {
            const proc = Gio.Subprocess.new(
                [this._clipCtl, 'add-text', '--stdin'],
                Gio.SubprocessFlags.STDIN_PIPE |
                Gio.SubprocessFlags.STDOUT_SILENCE |
                Gio.SubprocessFlags.STDERR_SILENCE
            );
            proc.communicate_utf8_async(text, null, (p, res) => {
                try {
                    p.communicate_utf8_finish(res);
                } catch (_e) {}
            });
        } catch (_e) {}
    }

    _notifyChange() {
        try {
            const proc = Gio.Subprocess.new(
                [this._clipCtl, 'notify-change'],
                Gio.SubprocessFlags.STDOUT_SILENCE |
                Gio.SubprocessFlags.STDERR_SILENCE
            );
            proc.wait_async(null, (p, res) => {
                try {
                    p.wait_finish(res);
                } catch (_e) {}
            });
        } catch (_e) {}
    }

    disable() {
        if (this._selection && this._ownerChangedId) {
            this._selection.disconnect(this._ownerChangedId);
            this._ownerChangedId = null;
        }
        this._selection = null;
        this._clipCtl = null;
    }
}
